#!/usr/bin/env python3
"""Extract the Siril functions used as test oracles, verbatim.

Writes siril_excerpt.c: every function below is copied byte-for-byte
from the Siril source tree (no edits), so the sref harness runs the
same C code Siril runs. Only the surrounding stubs (siril_stubs.h) are
ours.

    python3 extract_siril.py <siril-source-root> [output]   # write
    python3 extract_siril.py --check <siril-source-root>     # verify

--check regenerates in memory and fails if the committed
siril_excerpt.c differs, i.e. if the excerpt is not verbatim.

Standard library only.
"""

import hashlib
import os
import sys

# (file, first line of the block, end marker). A block runs from the
# first line that starts with `start` up to and including the first
# later line that equals `end`.
BLOCKS = [
    ("src/algos/statistics_float.c", "float siril_stats_float_sd(", "}"),
    ("src/algos/statistics_float.c", "double siril_stats_float_mad(", "}"),
    ("src/algos/statistics_float.c", "static float* reassign_to_non_null_data_float(", "}"),
    # The float sorting network uses this file-local macro.
    ("src/algos/sorting.c", "#define sw(i,j) if(a[i] > a[j]) { register float t=a[i]; a[i]=a[j]; a[j]=t; }", None),
    ("src/algos/sorting.c", "double sortnet_median_float(", "}"),
    ("src/algos/sorting.c", "double quickmedian_float(", "}"),
    ("src/algos/sorting.c", "double histogram_median_float(", "}"),
]

# rt_algo_excerpt.cc keeps its own header (it is C++); only the
# findMinMaxPercentile body is checked against the source.
RT_ALGO = ("src/rt/rt_algo.cc",
           "void findMinMaxPercentile(const float* data, size_t size, float minPrct, float* minOut, float maxPrct, float* maxOut, int threads)",
           "}")

HERE = os.path.dirname(os.path.abspath(__file__))


def extract(root, path, start, end):
    with open(os.path.join(root, path), encoding="utf-8") as f:
        lines = f.read().split("\n")
    for i, line in enumerate(lines):
        if line.startswith(start):
            if end is None:
                return line + "\n"
            for j in range(i + 1, len(lines)):
                if lines[j] == end:
                    return "\n".join(lines[i:j + 1]) + "\n"
            raise SystemExit(f"{path}: no end marker {end!r} after {start!r}")
    raise SystemExit(f"{path}: block {start!r} not found")


def sha256(root, path):
    with open(os.path.join(root, path), "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()


def render(root):
    out = [
        "/*",
        " * siril_excerpt.c -- GENERATED by extract_siril.py; do not edit.",
        " *",
        " * Functions copied verbatim from Siril (https://siril.org), GPL-3.0-or-later,",
        " * Copyright (C) 2005-2011 Francois Meyer, (C) 2012-2026 team free-astro.",
        " * Used only as a test oracle compiled into the sref harness; never linked",
        " * into the Go library.",
        " *",
        " * Source files (sha256 of the whole file):",
    ]
    for path in sorted({b[0] for b in BLOCKS}):
        out.append(f" *   {path}  {sha256(root, path)}")
    out += [" */", '#include "siril_stubs.h"', ""]
    for path, start, end in BLOCKS:
        out.append(f"/* ---- verbatim from {path} ---- */")
        out.append(extract(root, path, start, end))
    out.append("#undef sw")
    return "\n".join(out) + "\n"


def main():
    args = sys.argv[1:]
    check = False
    if args and args[0] == "--check":
        check = True
        args = args[1:]
    if not args:
        raise SystemExit(__doc__)
    root = args[0]
    text = render(root)

    rt_src = extract(root, *RT_ALGO)
    with open(os.path.join(HERE, "rt_algo_excerpt.cc"), encoding="utf-8") as f:
        rt_excerpt = f.read()
    if rt_src not in rt_excerpt:
        raise SystemExit("rt_algo_excerpt.cc: findMinMaxPercentile is not verbatim from " + RT_ALGO[0])

    target = os.path.join(HERE, "siril_excerpt.c") if len(args) < 2 else args[1]
    if check:
        with open(os.path.join(HERE, "siril_excerpt.c"), encoding="utf-8") as f:
            if f.read() != text:
                raise SystemExit("siril_excerpt.c differs from the Siril source at " + root)
        print("siril_excerpt.c and rt_algo_excerpt.cc are verbatim from", root)
        return
    with open(target, "w", encoding="utf-8") as f:
        f.write(text)
    print("wrote", target)


if __name__ == "__main__":
    main()
